# port scan plugin
yakit.AutoInitYakit()

/*
本插件定义的函数主要用于端口扫描的额外扩展

函数定义如下：
func(result *fp.MatchResult)

// 详细结构体定义与内容见模版结尾
// 这里最关键的是，如果对扫描出的结果有疑问，需要对 MatchResult 进行修改，应该直接
// 对变量.Field 进行修改。

DEMO:

handle = func(result) {
    if result.Fingerprint != nil {
        if result.Port == 80 && result.GetServiceName() == "" {
            result.Fingerprint.ServiceName = "http"
        }
    }
}

*/




handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    if len(result.Fingerprint.HttpFlows) <= 0{
        return
    }
    reqRaw := `GET /v1/agent/self HTTP/1.1
Host: {{params(target)}}`
    addr = str.HostPort(result.Target, result.Port)
    log.info(addr)
    isTls = str.IsTLSServer(addr)
    resp, req, err = poc.HTTP(reqRaw,poc.params({"target":addr}),poc.https(isTls))
    log.info(resp)
    if err != nil{
        return
    }
    rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
    urlIns, _ = str.ExtractURLFromHTTPRequestRaw(req, isTls)
    url = urlIns.String()
    if rspIns.StatusCode == 200 && str.MatchAllOfSubString(resp, `"EnableRemoteScriptChecks": true`){
        yakit.Info("发现%v存在Hashicorp Consul Service API远程命令执行漏洞", url)
        risk.NewRisk(url,
        risk.severity("high"),
        risk.title("Hashicorp Consul Service API远程命令执行漏洞"),
        risk.type("rce"),
        risk.typeVerbose("命令执行"),
        risk.payload(url),
        risk.request(req),
        risk.response(resp),
        risk.description("Consul是HashiCorp公司推出的一款开源工具，用于实现分布式系统的服务发现与配置。与其他分布式服务注册与发现的方案相比，Consul提供的方案更为“一站式”。Consul内置了服务注册与发现框架、分布一致性协议实现、健康检查、Key/Value存储、多数据中心方案，不再需要依赖其他工具（例如ZooKeeper等），使用方式也相对简单。  Consul使用Go语言编写，因此具有天然的可移植性（支持Linux、Windows和Mac OS X系统）；且安装包中仅包含一个可执行文件，便于部署，可与Docker等轻量级容器无缝配合。  在特定配置下，恶意攻击者可以通过发送精心构造的HTTP请求在未经授权的情况下在Consul服务端远程执行命令。"),
        risk.solution(`1、禁用Consul服务器上的脚本检查功能
2、确保Consul HTTP API服务无法通过外网访问或调用
3、对/v1/agent/service/register 禁止PUT方法`),
risk.details(
    {
        "验证":`：访问/v1/agent/self，如果EnableRemoteScriptChecks为true，则证明存在漏洞！`,
        "利用":`PUT访问/v1/agent/service/register接口，构造请求体{"ID": "id","Name": "name","Address":"目标ip","Port":目标端口,"check":{"Args": ["sh", "-c","命令"],"interval":"10s","Timeout":"86400s"}}
`
        }
),
        )
    }
}

/*
// 具体定义如下：
type palm/common/fp.(MatchResult) struct {
      Target: string  
      Port: int  
      State: fp.PortState  
      Reason: string  
      Fingerprint: *fp.FingerprintInfo  
  StructMethods(结构方法/函数): 
